choose.when:
AND t.UPDATE_TIME IS NOT NULL AND t.UPDATE_TIME <= #{updateHighWaterAt}
AND (#{updateLastAt,jdbcType=TIMESTAMP} IS NULL
     OR t.UPDATE_TIME > #{updateLastAt}
     OR (t.UPDATE_TIME=#{updateLastAt} AND t.ID > #{updateLastId}))

mapper.sql:
RUN_ID=#{runId} AND FLOW_KIND=#{flowKind} AND FLOW_STATE='RUNNING'
AND ACTIVE_PASS=#{pass} AND LEASE_TOKEN=#{leaseToken} AND ROW_VERSION=#{expectedRowVersion}
AND LEASE_UNTIL > SYSTIMESTAMP

    AND ID_LAST_ID=#{expected.idLastId}

        AND UPDATE_LAST_ID=#{expected.updateLastId}
        AND (UPDATE_LAST_AT=#{expected.updateLastAt,jdbcType=TIMESTAMP}
             OR (UPDATE_LAST_AT IS NULL AND #{expected.updateLastAt,jdbcType=TIMESTAMP} IS NULL))

    AND REVISIT_LAST_ID=#{expected.revisitLastId}
    AND 1=0

mapper.select:
SELECT * FROM (SELECT  FROM SMT_AUTH_LEGACY_REVIEW
WHERE PARK_STATE='KNOWN' AND ID > #{afterId}

    AND PARK_ID=#{requestedParkId}
    AND PARK_ID IN #{park}

AND REVIEW_STATE=#{reviewState}
ORDER BY ID) WHERE ROWNUM <= #{limit}

